<script setup>
import { ref,computed,watch,onMounted,onUnmounted,nextTick } from 'vue';
import { onBeforeRouteLeave,useRouter } from 'vue-router';
import { collection,getDocs } from 'firebase/firestore';
import { getAuth } from 'firebase/auth';
import { db } from '../firebase/config';
import { userProfile,userRole } from '../services/authService';
import { cargarRutasPatrulla,loadPatrullaConfig,cargarPatrullaPorId,crearPatrulla } from '../services/patrullaService';
import { savePatrolSheet } from '../services/patrolSheetService';
import { patrolValue,comparePatrol } from '../utils/patrolSheet';
import { DEFECTOS_TRAMA,ESTADOS_TELAR } from '../constants/organization';
import { vTippy } from '../utils/tooltipDirective';
import { Save,Check,RefreshCw,RotateCcw,X,Wrench } from 'lucide-vue-next';
import Swal from 'sweetalert2';
const props=defineProps({ patrulla:Object,canEdit:Boolean,coverage:Boolean,patrolOptions:{ type:Array,default:()=>[] },observer:Boolean }); const emit=defineEmits(['changed','select','coverage','pending']);
const router=useRouter(),patrol=ref(null),machines=ref([]),routes=ref([]),routeId=ref(''),config=ref({ umbralRoturaU:2,umbralRoturaT:3 });
const active=ref(1),presentation=ref('auto'),width=ref(globalThis.window?.innerWidth || 1360),loading=ref(true),busy=ref(false),error=ref(''),draft=ref({}),baseline=ref({});
const editor=ref(null),editorDraft=ref({}),editorInitial=ref(''),dialog=ref(null);
const roundKey=computed(()=>`ronda_${active.value}`),round=computed(()=>patrol.value?.rondas?.[roundKey.value] || {});
const dirty=computed(()=>JSON.stringify(draft.value)!==JSON.stringify(baseline.value));
const unlocked=computed(()=>active.value===1 || !!patrol.value?.rondas?.[`ronda_${active.value-1}`]?.completada);
const writable=computed(()=>props.canEdit && !!patrol.value?.id && !round.value.completada && unlocked.value && active.value<7 && !busy.value && !loading.value);
const full=computed(()=>presentation.value==='full' || (presentation.value==='auto' && width.value>=1200));
const shown=computed(()=>full.value ? [1,2,3,4,5,6,7]:[active.value]);
const selectedRoute=computed(()=>routes.value.find(route=>route.id===routeId.value));
const rows=computed(()=>{
  const byId=new Map(machines.value.map(machine=>[machine.id,machine]));
  let list=selectedRoute.value?.maquinas?.length ? [...selectedRoute.value.maquinas].sort((a,b)=>a.orden-b.orden).map(item=>byId.get(item.maquinaId)).filter(Boolean) : [...machines.value].sort((a,b)=>(a.orden_patrulla ?? 999)-(b.orden_patrulla ?? 999) || String(a.maquina).localeCompare(String(b.maquina),undefined,{ numeric:true }));
  const ids=new Set(list.map(machine=>machine.id));
  for(const data of Object.values(patrol.value?.rondas || {})) for(const id of Object.keys(data.datos || {})) if(!ids.has(id)) { list.push(byId.get(id) || { id,maquina:id,tipo:'Registro histórico' }); ids.add(id); }
  return list;
});
const label=machine=>{ const value=String(machine.maquina || machine.id); return /^\d+$/.test(value) ? String(Number(value.slice(-2))):value; };
const title=n=>({1:'Roturas',2:'Paro/Defecto',3:'Trama negra',4:'Paro/Defecto',5:'Paro/Defecto',6:'Roturas',7:'Evaluación'}[n]);
const status=n=>patrol.value?.rondas?.[`ronda_${n}`]?.completada ? 'Completada':patrol.value?.rondas?.[`ronda_${n}`]?.datos ? 'En curso':'Pendiente';
function seed() { const data=patrol.value?.rondas?.[roundKey.value]?.datos || {}; draft.value=JSON.parse(JSON.stringify(data)); baseline.value=JSON.parse(JSON.stringify(data)); }
function values(n,id) { return n===active.value ? draft.value[id] || {} : patrol.value?.rondas?.[`ronda_${n}`]?.datos?.[id] || {}; }
function display(value) { return value==null || value==='' ? '':String(value).replace('.',','); }
function numberInput(id,field,event) { if(!writable.value) return; draft.value[id]={ ...(draft.value[id] || {}),[field]:event.target.value,hora:draft.value[id]?.hora || new Date().toISOString() }; }
function alertValue(n,id,field) { try { const value=patrolValue(values(n,id)[field]); return value!=null && value>Number(config.value[field==='roU' ? 'umbralRoturaU':'umbralRoturaT']); } catch { return false; } }
function evaluation(id,field) { const rounds=patrol.value?.rondas || {}; if(!rounds.ronda_1?.completada || !rounds.ronda_6?.completada) return 'Sin datos'; return { mejor:'Mejoró',peor:'Empeoró',leve:'Leve ↑',igual:'Igual',missing:'Sin datos' }[comparePatrol(rounds.ronda_1.datos?.[id]?.[field],rounds.ronda_6.datos?.[id]?.[field])]; }
function cellText(n,id) { const data=values(n,id); if(n===3) return data.sinDefectos ? 'Sin defectos':data.defectos?.length ? data.defectos.map(key=>DEFECTOS_TRAMA.find(item=>item.id===key)?.label || key).join(', '):'Sin revisar'; return [ESTADOS_TELAR.find(item=>item.id===data.estado)?.label || data.estado,data.observacion].filter(Boolean).join(' · ') || 'Sin relevar'; }
let generation=0,previousFocus;
watch(()=>props.patrulla,record=>{ if(record?.id!==patrol.value?.id || !dirty.value) { const changed=record?.id!==patrol.value?.id; patrol.value=record; seed(); if(changed && !loading.value) load(); } },{ immediate:true });
async function load() {
  if(busy.value) return;
  if(dirty.value && !await discard()) return;
  const token=++generation; loading.value=true; error.value='';
  try {
    const sector=patrol.value?.sector || userProfile.value?.sectorDefault || 'TEJEDURIA';
    const result=await Promise.all([getDocs(collection(db,'maquinas')),cargarRutasPatrulla('roturas',sector),loadPatrullaConfig(),patrol.value?.id ? cargarPatrullaPorId(patrol.value.id):Promise.resolve(null)]);
    if(token!==generation) return;
    machines.value=result[0].docs.map(item=>({ ...item.data(),id:item.id })).filter(machine=>machine.tipo==='TELAR' && machine.sector===sector && machine.activo!==false);
    routes.value=result[1]; config.value=result[2]; if(result[3]) patrol.value=result[3];
    const stored=patrol.value?.rondas?.ronda_1?.rutaId; routeId.value=routes.value.find(route=>route.id===stored)?.id || routes.value.find(route=>route.obligatoria)?.id || routes.value.find(route=>route.esDefault)?.id || routes.value[0]?.id || ''; seed(); restoreIntervention();
  } catch(failure) { if(token===generation) error.value=failure.message || 'No se pudo cargar la planilla.'; }
  finally { if(token===generation) loading.value=false; }
}
async function begin() { if(busy.value || !props.canEdit || patrol.value) return; busy.value=true; try { const user=getAuth().currentUser; if(!user) throw new Error('Ingresá nuevamente.'); const result=await crearPatrulla({ inspectorUid:user.uid,inspectorNombre:userProfile.value?.nombre || user.displayName || 'Inspector',inspectorEmail:user.email || '',sector:userProfile.value?.sectorDefault || 'TEJEDURIA' }); patrol.value=await cargarPatrullaPorId(result.id); seed(); emit('changed',patrol.value); } catch(failure) { error.value=failure.message; } finally { busy.value=false; } }
async function discard() { if(busy.value) return false; if(!dirty.value) return true; if(!(await Swal.fire({ title:'¿Descartar cambios de la ronda?',text:'Los datos todavía no se guardaron.',icon:'warning',showCancelButton:true,confirmButtonText:'Descartar',cancelButtonText:'Cancelar' })).isConfirmed) return false; seed(); return true; }
async function changeRound(event) { const number=Number(event.target.value); if(!await discard()) { event.target.value=active.value; return; } active.value=number; seed(); }
async function changeRoute(event) { const next=event.target.value; if(!await discard()) { event.target.value=routeId.value; return; } routeId.value=next; }
function buildData() { const data={}; for(const [id,value] of Object.entries(draft.value)) { const entry={ ...value }; if([1,6].includes(active.value)) { entry.roU=patrolValue(value.roU); entry.roT=patrolValue(value.roT); if(entry.roU==null && entry.roT==null) continue; } else if(active.value===3) { if(!entry.sinDefectos && !entry.defectos?.length) continue; if(entry.metros==='' || entry.metros==null) entry.metros=null; else { entry.metros=Number(String(entry.metros).replace(',','.')); if(!Number.isFinite(entry.metros) || entry.metros<0) throw new Error('Metros inválidos.'); } } else if(!entry.estado) continue; data[id]=entry; } return data; }
async function save(complete=false,reopen=false) {
  if(busy.value || !props.canEdit || !patrol.value?.id || active.value===7 || !reopen && !writable.value) return false;
  busy.value=true; error.value='';
  try {
    if(reopen && !(await Swal.fire({ title:'¿Reabrir ronda?',text:'Se conservan los datos y se actualizará la evaluación al completar las roturas.',icon:'question',showCancelButton:true,confirmButtonText:'Reabrir',cancelButtonText:'Cancelar' })).isConfirmed) return false;
    const data=reopen ? {}:buildData();
    if(!reopen && !Object.keys(data).length) throw new Error('Registrá al menos un telar antes de guardar.');
    if(complete && !(await Swal.fire({ title:`¿Completar ronda ${active.value}?`,text:`Se guardarán ${Object.keys(data).length} telares. Quedará en solo lectura hasta reabrirla.`,icon:'question',showCancelButton:true,confirmButtonText:'Completar',cancelButtonText:'Cancelar' })).isConfirmed) return false;
    patrol.value=await savePatrolSheet(patrol.value.id,roundKey.value,round.value,data,complete,{ rutaId:routeId.value,rutaNombre:selectedRoute.value?.nombre || '',...(props.coverage ? { cubiertoPor:getAuth().currentUser.uid,cubiertoNombre:userProfile.value?.nombre || '' }: {}) },reopen);
    seed(); const returned=readIntervention(); if(returned?.patrullaId===patrol.value.id && returned.rondaKey===roundKey.value) sessionStorage.removeItem('patrol_intervention_return'); emit('changed',patrol.value); return true;
  } catch(failure) { error.value=failure.message; return false; }
  finally { busy.value=false; }
}
function readIntervention() { try { return JSON.parse(globalThis.sessionStorage?.getItem('patrol_intervention_return') || 'null'); } catch { return null; } }
function restoreIntervention() { const ret=readIntervention(); if(!ret || !patrol.value?.id || ret.patrullaId!==patrol.value.id || ![2,4,5].includes(Number(ret.rondaKey?.slice(-1)))) return; active.value=Number(ret.rondaKey.slice(-1)); seed(); if(ret.sintomaLabel || ret.obsRaw) { const entry=draft.value[ret.telarId]; if(entry) draft.value[ret.telarId]={ ...entry,intervencion:{ tipo:ret.tipoInterv || '',sintoma:ret.sintomaLabel || '',obs:ret.obsRaw || '',hora:new Date().toISOString() },observacion:entry.observacion || [ret.sintomaLabel,ret.obsRaw].filter(Boolean).join(' — ') }; } }
function navigateCell(event) { const delta={ Enter:1,ArrowRight:1,ArrowLeft:-1,ArrowUp:-2,ArrowDown:2 }[event.key]; if(delta==null) return; event.preventDefault(); const cells=[...event.target.closest('table').querySelectorAll('input:not(:disabled)')],index=cells.indexOf(event.target); const next=cells[index+delta]; next?.focus(); next?.select(); }
function openCell(n,machine) { previousFocus=globalThis.document?.activeElement; editor.value={ n,machine }; const current=values(n,machine.id); editorDraft.value={ ...JSON.parse(JSON.stringify(current)),estado:current.estado || '',observacion:current.observacion || '',defectos:[...(current.defectos || [])],sinDefectos:!!current.sinDefectos,metros:current.metros ?? '' }; editorInitial.value=JSON.stringify(editorDraft.value); nextTick(()=>dialog.value?.focus?.()); }
async function closeCell() { if(JSON.stringify(editorDraft.value)!==editorInitial.value && !(await Swal.fire({ title:'¿Descartar esta celda?',icon:'question',showCancelButton:true,confirmButtonText:'Descartar',cancelButtonText:'Cancelar' })).isConfirmed) return; editor.value=null; nextTick(()=>previousFocus?.isConnected && previousFocus.focus()); }
function applyCell() { if(!writable.value || editor.value.n!==active.value) return; const current=draft.value[editor.value.machine.id] || {}; const value=active.value===3 ? { ...current,defectos:[...editorDraft.value.defectos],sinDefectos:editorDraft.value.sinDefectos,metros:editorDraft.value.metros,hora:editorDraft.value.hora || new Date().toISOString() } : { ...current,estado:editorDraft.value.estado,observacion:editorDraft.value.observacion,defectoCalidad:editorDraft.value.defectoCalidad || '',hora:editorDraft.value.hora || new Date().toISOString() }; if(active.value===3 && value.sinDefectos) value.defectos=[]; draft.value[editor.value.machine.id]=value; editor.value=null; nextTick(()=>previousFocus?.isConnected && previousFocus.focus()); }
async function intervention() { const machine=editor.value.machine; applyCell(); if(!await save(false)) return; const entry=draft.value[machine.id]; sessionStorage.setItem('patrol_intervention_return',JSON.stringify({ patrullaId:patrol.value.id,telarId:machine.id,rondaKey:roundKey.value,tipoInterv:entry.estado==='paro_electrico' ? 'ELECTRICO':'MECANICO' })); router.push({ path:'/llamar',query:{ maqId:machine.id,tipo:'TELAR',grp:String(machine.grp_tear || ''),obs:entry.observacion || '',tipoInterv:entry.estado==='paro_electrico' ? 'ELECTRICO':'MECANICO',origen:'patrulla' } }); }
function keyboard(event) { if(event.key==='Escape') { event.stopPropagation(); closeCell(); } if(event.key!=='Tab') return; const nodes=[...(dialog.value?.querySelectorAll('button:not(:disabled),select:not(:disabled),textarea:not(:disabled),input:not(:disabled)') || [])].filter(node=>node.getClientRects().length); const first=nodes[0],last=nodes.at(-1),current=globalThis.document?.activeElement; if(!first) { event.preventDefault(); return; } if(event.shiftKey && (current===first || !nodes.includes(current))) { event.preventDefault(); last.focus(); } else if(!event.shiftKey && (current===last || !nodes.includes(current))) { event.preventDefault(); first.focus(); } }
function beforeUnload(event) { if(dirty.value || busy.value || editor.value && JSON.stringify(editorDraft.value)!==editorInitial.value) { event.preventDefault(); event.returnValue=''; } }
async function selectPatrol(event) { if(await discard()) emit('select',event.target.value); else event.target.value=patrol.value?.id || ''; }
async function toggleCoverage() { if(await discard()) emit('coverage'); }
watch([dirty,busy,editor,()=>JSON.stringify(editorDraft.value)],()=>emit('pending',dirty.value || busy.value || !!editor.value && JSON.stringify(editorDraft.value)!==editorInitial.value));
const resize=()=>width.value=window.innerWidth;
onMounted(()=>{ load(); window.addEventListener('resize',resize); window.addEventListener('beforeunload',beforeUnload); });
onUnmounted(()=>{ generation++; window.removeEventListener('resize',resize); window.removeEventListener('beforeunload',beforeUnload); });
onBeforeRouteLeave(async()=>{ if(busy.value) return false; if(editor.value) { await closeCell(); if(editor.value) return false; } return await discard(); });
</script>
<template>
<section class="patrol-sheet" :inert="editor || undefined"><header class="sheet-header"><div><h1>Patrulla de control de calidad</h1><p>{{ patrol?.fecha || 'Turno actual' }} · Turno {{ patrol?.turno || '—' }} · Inspector: {{ patrol?.inspectorNombre || userProfile?.nombre || '—' }} · Supervisor: {{ patrol?.supervisorNombre || 'No informado' }}</p></div><button class="btn" :disabled="busy" @click="load"><RefreshCw />Actualizar</button></header><div class="controls"><label v-if="patrolOptions.length>1">Inspector<select :value="patrol?.id" :disabled="busy" @change="selectPatrol"><option v-for="option in patrolOptions" :key="option.id" :value="option.id">{{ option.inspectorNombre || option.inspectorEmail || option.id }}</option></select></label><button v-if="observer" class="btn" :disabled="busy" @click="toggleCoverage">{{ coverage ? 'Salir de cobertura':'Cubrir inspector' }}</button><label>Ruta<select :value="routeId" :disabled="busy || !!selectedRoute?.obligatoria" @change="changeRoute"><option v-if="!routes.length" value="">Orden de patrulla</option><option v-for="route in routes" :key="route.id" :value="route.id">{{ route.nombre }}</option></select></label><label>Ronda<select :value="active" :disabled="busy" @change="changeRound"><option v-for="n in 7" :key="n" :value="n">{{ n }} · {{ title(n) }} · {{ status(n) }}</option></select></label><label>Vista<select v-model="presentation"><option value="auto">Según pantalla</option><option value="full">Planilla completa</option><option value="round">Ronda elegida</option></select></label><span class="round-state">{{ status(active) }}{{ !unlocked && active<7 ? ' · Completá la ronda anterior':'' }}{{ !canEdit ? ' · Solo lectura':'' }}</span></div><p v-if="error" class="error" role="alert">{{ error }}</p><div v-if="!patrol" class="empty-patrol"><p>Planilla sin datos del turno. Iniciá una patrulla para cargar.</p><button v-if="canEdit" class="btn primary" :disabled="busy || loading" @click="begin">Iniciar patrulla del turno</button></div><div class="table-panel"><div class="table-scroll"><p v-if="loading" class="empty">Cargando planilla…</p><table v-else :class="{ full }"><colgroup><col style="width:58px" /><template v-for="n in shown" :key="n"><col v-for="field in n===1 || n===6 ? [1,2]:[]" :key="field" :style="full ? { width:'64px' }:{}" /><col v-if="[2,4,5].includes(n)" /><col v-for="turno in n===3 ? ['A','B','C']:[]" :key="turno" :style="full ? { width:'34px' }:{}" /><col v-if="n===7" :style="full ? { width:'130px' }:{}" /></template></colgroup><thead><tr><th rowspan="2" class="sticky-machine">Telar</th><th v-for="n in shown" :key="n" :colspan="n===1 || n===6 ? 2:n===3 ? 3:1" :class="{ active:n===active }">{{ n }} · {{ title(n) }}</th></tr><tr><template v-for="n in shown" :key="n"><th v-if="n===1 || n===6">Ro.U</th><th v-if="n===1 || n===6">Ro.T</th><th v-if="[2,4,5].includes(n)">Paro / Defecto</th><th v-for="turno in n===3 ? ['A','B','C']:[]" :key="turno">{{ turno }}</th><th v-if="n===7">R1 → R6</th></template></tr></thead><tbody><tr v-for="machine in rows" :key="machine.id"><th class="sticky-machine" v-tippy="`${machine.maquina} · ${machine.grp_tear || ''}`">{{ label(machine) }}</th><template v-for="n in shown" :key="n"><td v-for="field in n===1 || n===6 ? ['roU','roT']:[]" :key="field" class="number" :class="{ alert:alertValue(n,machine.id,field),active:n===active }"><input :value="display(values(n,machine.id)[field])" :aria-label="`Telar ${label(machine)}, ronda ${n}, ${field}`" :disabled="n!==active || !writable || n===6 && !patrol?.rondas?.ronda_1?.datos?.[machine.id]" inputmode="decimal" @input="numberInput(machine.id,field,$event)" @focus="$event.target.select()" @keydown="navigateCell" /><span v-if="alertValue(n,machine.id,field)" v-tippy="'Supera el umbral de roturas configurado'" class="warning">!</span></td><td v-if="[2,4,5].includes(n)" class="observation"><button v-tippy="cellText(n,machine.id)" @click="openCell(n,machine)">{{ cellText(n,machine.id) }}</button><span v-if="values(n,machine.id).intervencion" class="linked">Intervención vinculada</span></td><td v-for="turno in n===3 ? ['A','B','C']:[]" :key="turno" class="trama"><button v-if="turno===patrol?.turno" v-tippy="cellText(n,machine.id)" @click="openCell(n,machine)">{{ values(n,machine.id).sinDefectos ? '✓':values(n,machine.id).defectos?.length ? '⚠':'—' }}</button><span v-else v-tippy="'El control pertenece al turno de esta patrulla'">—</span></td><td v-if="n===7" class="evaluation"><span :class="{ problem:['Empeoró','Leve ↑'].includes(evaluation(machine.id,'roU')) }">U: {{ evaluation(machine.id,'roU') }}</span><span :class="{ problem:['Empeoró','Leve ↑'].includes(evaluation(machine.id,'roT')) }">T: {{ evaluation(machine.id,'roT') }}</span></td></template></tr></tbody></table><p v-if="!loading && !rows.length" class="empty">No hay telares en la ruta seleccionada.</p></div><footer class="sheet-footer"><span>{{ rows.length }} telares · {{ dirty ? 'Cambios sin guardar':'Datos guardados' }}</span><div><button v-if="canEdit && round.completada && active<7" class="btn" :disabled="busy" @click="save(false,true)"><RotateCcw />Reabrir ronda</button><button v-if="writable" class="btn" :disabled="busy || !dirty" @click="save(false)"><Save />Guardar borrador</button><button v-if="writable" class="btn primary" :disabled="busy" @click="save(true)"><Check />Completar ronda {{ active }}</button><span v-if="busy">Guardando…</span><span v-if="active===7">Evaluación automática</span></div></footer></div></section>
<Teleport to="body"><div v-if="editor" class="cell-backdrop" @click.self="closeCell"><form ref="dialog" class="cell-dialog" role="dialog" aria-modal="true" aria-label="Control del telar" tabindex="-1" @keydown="keyboard" @submit.prevent="applyCell"><header><h2>Telar {{ label(editor.machine) }} · Ronda {{ editor.n }}</h2><button class="btn" type="button" aria-label="Cerrar celda" @click="closeCell"><X /></button></header><fieldset :disabled="!writable || editor.n!==active"><template v-if="editor.n===3"><label class="check"><input type="checkbox" v-model="editorDraft.sinDefectos" />Sin defectos</label><div class="defects"><label v-for="defect in DEFECTOS_TRAMA" :key="defect.id" class="check"><input type="checkbox" :value="defect.id" v-model="editorDraft.defectos" :disabled="editorDraft.sinDefectos" />{{ defect.label }}</label></div><label>Metros controlados<input v-model="editorDraft.metros" inputmode="decimal" /></label></template><template v-else><label>Estado<select v-model="editorDraft.estado"><option value="">Sin relevar</option><option v-for="state in ESTADOS_TELAR" :key="state.id" :value="state.id">{{ state.label }}</option></select></label><label v-if="editorDraft.estado==='paro_calidad'">Defecto<select v-model="editorDraft.defectoCalidad"><option value="">Seleccionar</option><option v-for="defect in DEFECTOS_TRAMA" :key="defect.id" :value="defect.id">{{ defect.label }}</option></select></label><label>Observaciones<textarea v-model="editorDraft.observacion" rows="4" /></label></template></fieldset><footer><button type="button" class="btn" @click="closeCell">Cerrar</button><button v-if="writable && editor.n===active && ['paro_mecanico','paro_electrico'].includes(editorDraft.estado)" type="button" class="btn" @click="intervention"><Wrench />Solicitar intervención</button><button v-if="writable && editor.n===active" class="btn primary" type="submit">Aplicar a la planilla</button></footer></form></div></Teleport>
